import type { CSSProperties } from 'react';

/**
 * The responsive photo set, generated by `scripts/optimise-images.mjs`.
 * Globbing keeps the widths in one place: add a file, get a candidate.
 */
const files = import.meta.glob<string>('../assets/images/*.{webp,jpg}', {
  eager: true,
  query: '?url',
  import: 'default',
});

type Candidate = { url: string; width: number };

function candidates(name: string, extension: 'webp' | 'jpg'): Candidate[] {
  const pattern = new RegExp(`/${name}-(\\d+)\\.${extension}$`);
  return Object.entries(files)
    .map(([path, url]) => {
      const match = pattern.exec(path);
      return match ? { url, width: Number(match[1]) } : null;
    })
    .filter((candidate): candidate is Candidate => candidate !== null)
    .sort((a, b) => a.width - b.width);
}

function srcSet(list: Candidate[]) {
  return list.map((candidate) => `${candidate.url} ${candidate.width}w`).join(', ');
}

type PhotoProps = {
  /** File stem, e.g. `kyles-of-bute` for `kyles-of-bute-1400.webp`. */
  name: string;
  alt: string;
  /** The `sizes` attribute — how wide the image renders at each breakpoint. */
  sizes: string;
  loading?: 'lazy' | 'eager';
  fetchPriority?: 'high' | 'low' | 'auto';
  className?: string;
  style?: CSSProperties;
};

/** A `<picture>` that serves WebP with a JPEG fallback, at the right width. */
export function Photo({
  name,
  alt,
  sizes,
  loading = 'lazy',
  fetchPriority = 'auto',
  className,
  style,
}: PhotoProps) {
  const webp = candidates(name, 'webp');
  const jpeg = candidates(name, 'jpg');
  const fallback = jpeg.at(-1) ?? webp.at(-1);

  if (!fallback) {
    throw new Error(`No image files found for "${name}"`);
  }

  return (
    <picture>
      {webp.length > 0 && <source type="image/webp" srcSet={srcSet(webp)} sizes={sizes} />}
      <img
        src={fallback.url}
        srcSet={jpeg.length > 0 ? srcSet(jpeg) : undefined}
        sizes={sizes}
        alt={alt}
        loading={loading}
        fetchPriority={fetchPriority}
        decoding="async"
        className={className}
        style={style}
      />
    </picture>
  );
}
